import{_ as t,o as r,c as e,a2 as s}from"./chunks/framework.B2QVIpOM.js";const h=JSON.parse('{"title":"赛马会体艺中学 · 2022/23资料年份 · 中一 · 面试","description":"","frontmatter":{"schema":"exam-report-v3","generated_from":"assets/exam-feedback","school_slug":"school-4936c36d","school_zh":"赛马会体艺中学","school_en":"—","grade":"s1","year":"2022-23","year_label":"2022/23资料年份","type":"interview","title":"赛马会体艺中学 · 2022/23资料年份 · 中一 · 面试","anonymous":true,"source_ids":["C2223-TIC-FIRST","C2223-TIC-SECOND"],"rounds":["r1","r2"]},"headers":[],"relativePath":"reports/school-4936c36d/s1/2022-23-interview.md","filePath":"reports/school-4936c36d/s1/2022-23-interview.md"}'),p={name:"reports/school-4936c36d/s1/2022-23-interview.md"};function n(a,o,c,l,g,i){return r(),e("div",null,[...o[0]||(o[0]=[s('<h1 id="赛马会体艺中学-·-2022-23资料年份-·-中一-·-面试" tabindex="-1">赛马会体艺中学 · 2022/23资料年份 · 中一 · 面试 <a class="header-anchor" href="#赛马会体艺中学-·-2022-23资料年份-·-中一-·-面试" aria-label="Permalink to &quot;赛马会体艺中学 · 2022/23资料年份 · 中一 · 面试&quot;">​</a></h1><p><a href="/hk-exam-web/schools/school-4936c36d">← 返回赛马会体艺中学资料库</a></p><blockquote><p>以下内容根据考试及面试资料整理，已作匿名化与书面化处理，非逐字实录。具体安排请以当次考试通知为准。</p></blockquote><h2 id="record-c2223-tic-first" tabindex="-1">资料来源：【其它机构】升中一面試真题汇总记录_22-23.pdf <a class="header-anchor" href="#record-c2223-tic-first" aria-label="Permalink to &quot;资料来源：【其它机构】升中一面試真题汇总记录_22-23.pdf {#record-c2223-tic-first}&quot;">​</a></h2><p><strong>资料类型：</strong> 不同学生的历史面试反馈汇编</p><p><strong>入学途径：</strong> 中一入学</p><p><strong>课程分支：</strong> 课程分支未注明</p><h3 id="第一轮-·-原文明示" tabindex="-1">第一轮 · 原文明示 <a class="header-anchor" href="#第一轮-·-原文明示" aria-label="Permalink to &quot;第一轮 · 原文明示&quot;">​</a></h3><blockquote><p><strong>考核安排：</strong></p><p><strong>首轮筛选与准备</strong></p><p>该组反馈首轮在2月25日举行，并非所有申请者均获面试。申请表有学生亲笔填写部分，获首轮邀请后需准备体育录像或视艺作品集。有家庭另附学术资料并获接收，但未说明这是统一要求。</p><p><strong>三个环节</strong></p><p>包括英语小组、个人会面，以及体育或视艺测试。体育考生可穿运动服到校，并有热身时间；该次有学生可自行离校，无须家长接送。</p></blockquote><blockquote><p><strong>英语：</strong> 英语</p><p><strong>三人轮流作答</strong></p><p>一位老师面见三名考生，轮流回答，没有考生之间的讨论。题目包括推荐一本读过的英文书并说明原因，以及给出6个英文词，在10秒内组成一句话。</p></blockquote><blockquote><p><strong>个人面谈：</strong> 中文、英语</p><p><strong>资料追问与职业目标</strong></p><p>两位老师在场，一位先问，另一位查看申请资料后继续问；会检查手册和家课册并给予意见。问未来想从事什么工作、如何提升自己的专项运动，并根据回答追问。</p><p><strong>语言切换</strong></p><p>一名考生先用英语作答，老师表示英文口语表现可以后，改用中文继续；其他考生是否同样切换语言未获确认。</p></blockquote><blockquote><p><strong>体育：</strong> 语言未注明</p><p><strong>400米跑</strong></p><p>有学生助手计时；考生观察到部分同场学生跑至中途感到吃力。</p><p><strong>排球对墙传球与立定跳远</strong></p><p>距离墙约1.5至2米，将排球抛向墙上的指定方框，考生观察到不少球超出范围。立定跳远有3次机会。该名考生当天没有接受自己专项运动的技术测试。</p></blockquote><blockquote><p><strong>视艺：</strong> 语言未注明</p><p><strong>现场完成作品</strong></p><p>家长了解到视艺组需在现场完成作品，作画节奏较宽松；此项为家长转述，并非该名体育考生亲历。</p></blockquote><h2 id="record-c2223-tic-second" tabindex="-1">资料来源：【其它机构】升中一面試真题汇总记录_22-23.pdf <a class="header-anchor" href="#record-c2223-tic-second" aria-label="Permalink to &quot;资料来源：【其它机构】升中一面試真题汇总记录_22-23.pdf {#record-c2223-tic-second}&quot;">​</a></h2><p><strong>资料类型：</strong> 不同学生的历史面试反馈汇编</p><p><strong>入学途径：</strong> 中一入学</p><p><strong>课程分支：</strong> 课程分支未注明</p><h3 id="第二轮-·-原文明示" tabindex="-1">第二轮 · 原文明示 <a class="header-anchor" href="#第二轮-·-原文明示" aria-label="Permalink to &quot;第二轮 · 原文明示&quot;">​</a></h3><blockquote><p><strong>考核安排：</strong></p><p><strong>电话邀请与不同场次</strong></p><p>首轮后数日开始电话邀请，该组反馈的次轮安排在3月3日至27日，部分为上课日，需要请假。有人参加校长小组面试，也有人为个人形式。</p></blockquote><blockquote><p><strong>校长面试：</strong> 英语</p><p><strong>四人小组与聆听追问</strong></p><p>一组为2名体育及2名视艺考生共同面见校长，全程英语，约25至30分钟，轮流发言。问未来职业、用一个形容词描述与家人的关系，以及体育或视艺专长怎样帮助达到职业要求。校长也会请考生回应其他人的发言，检查是否留意同伴的回答。</p></blockquote><blockquote><p><strong>副校长及家长面谈：</strong> 中文（口语未注明）</p><p><strong>先见学生，再邀请父母</strong></p><p>学生先独自与副校长交谈，再到等候室邀请父母一同进入。问题包括为何选择体艺中学，以及若校内发生欺凌，家长会怎样处理。</p></blockquote><blockquote><p><strong>家长反馈：</strong></p><p><strong>交流气氛与前一环节意见</strong></p><p>家长感觉气氛轻松，以交谈为主；有副校长表示已通过iPad看到刚才校长给予的意见。</p></blockquote>',22)])])}const u=t(p,[["render",n]]);export{h as __pageData,u as default};
